#include "v84-warm-pdhg.hpp"

#include <cmath>
#include <cstdio>
#include <limits>
#include <stdexcept>
#include <string_view>
#include <utility>
#include <vector>

namespace {

namespace warm = solver::v84_warm_pdhg;
using Index = warm::Index;
std::vector<const char*> details;

void require(bool condition, const char* message) {
  if (!condition) throw std::runtime_error(message);
}

bool status(const warm::Result& result, const char* expected) { return std::string_view(result.status) == expected; }

struct Fixture {
  Index n, m;
  std::vector<Index> starts, rows;
  std::vector<double> values, costs, rhs;
  std::vector<bool> inequality;
  warm::View view() const { return {n, m, starts, rows, values, costs, rhs, inequality}; }
};

// 独立按完整 LP 的原始违反、驻点残差和目标差验收，不用内核步长或迭代差代替终验。
bool optimal(const Fixture& f, const std::vector<double>& x, const std::vector<double>& z, long double tolerance = 1e-9L) {
  if (x.size() != static_cast<std::size_t>(f.n) || z.size() != static_cast<std::size_t>(f.m)) return false;
  std::vector<long double> activity(static_cast<std::size_t>(f.m), 0), transpose(static_cast<std::size_t>(f.n), 0);
  long double primal_objective = 0, dual_term = 0;
  for (Index col = 0; col < f.n; ++col) {
    if (!std::isfinite(x[static_cast<std::size_t>(col)])) return false;
    primal_objective += static_cast<long double>(f.costs[static_cast<std::size_t>(col)]) * x[static_cast<std::size_t>(col)];
    for (Index k = f.starts[static_cast<std::size_t>(col)]; k < f.starts[static_cast<std::size_t>(col + 1)]; ++k) {
      const auto entry = static_cast<std::size_t>(k), row = static_cast<std::size_t>(f.rows[entry]);
      activity[row] += static_cast<long double>(f.values[entry]) * x[static_cast<std::size_t>(col)];
      transpose[static_cast<std::size_t>(col)] += static_cast<long double>(f.values[entry]) * z[row];
    }
  }
  for (Index row = 0; row < f.m; ++row) {
    const auto i = static_cast<std::size_t>(row);
    if (!std::isfinite(z[i]) || (f.inequality[i] && z[i] < 0)) return false;
    const long double defect = activity[i] - f.rhs[i];
    const long double bound = tolerance * (1 + std::abs(static_cast<long double>(f.rhs[i])));
    if (f.inequality[i] ? defect > bound : std::abs(defect) > bound) return false;
    dual_term += static_cast<long double>(f.rhs[i]) * z[i];
  }
  for (Index col = 0; col < f.n; ++col) {
    const auto i = static_cast<std::size_t>(col);
    if (std::abs(transpose[i] + f.costs[i]) > tolerance * (1 + std::abs(static_cast<long double>(f.costs[i])))) return false;
  }
  return std::abs(primal_objective + dual_term) <= tolerance * (1 + std::abs(primal_objective) + std::abs(dual_term));
}

void ledger(const warm::Result& result, const warm::Limits& limits) {
  const auto& s = result.stats;
  require(s.setup_completed <= s.setup_started && s.setup_started <= 1 &&
      s.steps_completed <= s.multiply_completed && s.multiply_completed <= s.multiply_started &&
      s.multiply_started <= s.transpose_completed && s.transpose_completed <= s.transpose_started &&
      s.transpose_started <= s.steps_started && s.steps_started - s.steps_completed <= 1 &&
      s.work_units <= limits.max_work && s.assessments_completed <= s.assessments_started &&
      s.assessments_started - s.assessments_completed <= 1, "已提交步、两个乘积与部分工作账本必须一致");
  require(s.last_assessed_step.has_value() == (s.assessments_completed > 0) &&
      (!s.last_assessed_step || *s.last_assessed_step <= s.steps_completed), "最后验收只可关联已提交点");
}

void convergence() {
  const std::vector<Fixture> fixtures{
    {1, 1, {0, 1}, {0}, {1}, {-1}, {1}, {true}},
    {1, 1, {0, 1}, {0}, {2}, {2}, {6}, {false}},
    {2, 3, {0, 2, 5}, {0, 1, 0, 1, 2}, {1, -3, 2, 1, 1}, {4.25, -0.25}, {5, -1, 4}, {false, true, true}}
  };
  for (const auto& f : fixtures) {
    warm::Limits limits;
    std::vector<double> x(static_cast<std::size_t>(f.n), 0), z(static_cast<std::size_t>(f.m), 0);
    warm::Result result;
    warm::run(f.view(), limits, x, z, 2, {}, [&](Index, const auto& a, const auto& b) { return optimal(f, a, b); }, result);
    require(result.accepted && status(result, "accepted") && optimal(f, result.x, result.z), "不等式、等式和混合 LP 均须通过独立完整验收");
    ledger(result, limits);
  }
  details.push_back("不等式等式混合完整LP验收");
}

void seed_and_step() {
  const Fixture equality{1, 1, {0, 1}, {0}, {2}, {2}, {6}, {false}};
  const std::vector<double> exact_x{9}, exact_z{-3};
  warm::Limits limits;
  warm::Result seed;
  warm::run(equality.view(), limits, exact_x, exact_z, 3, {}, [&](Index step, const auto& x, const auto& z) {
    require(step == 0 && x == std::vector<double>{3} && z == std::vector<double>{-1}, "种子须同时除以真实 tau");
    return optimal(equality, x, z);
  }, seed);
  require(seed.accepted && seed.stats.steps_started == 0 && seed.stats.setup_started == 0 &&
      seed.stats.assessments_completed == 1, "种子已达标不得伪造迭代或范数装配");
  const Fixture f{2, 2, {0, 2, 4}, {0, 1, 0, 1}, {1, -3, 2, 4}, {0.5, -2}, {2, -1}, {true, false}};
  const std::vector<double> x{2, -4}, z{1, -2};
  warm::Limits one; one.max_iterations = 1;
  warm::Result result;
  std::vector<Index> evaluated;
  warm::run(f.view(), one, x, z, 2, {}, [&](Index step, const auto&, const auto&) { evaluated.push_back(step); return false; }, result);
  require(!result.accepted && status(result, "iteration_limit") && evaluated == std::vector<Index>({0, 1}) &&
      std::abs(result.x[0] - 0.1) < 1e-14 && std::abs(result.x[1] + 1.25) < 1e-14 &&
      result.z[0] == 0 && std::abs(result.z[1] + 0.82) < 1e-14,
      "非对称完整矩阵须使用列行和步长、primal-first、外推及正确投影");
  require(x == std::vector<double>({2, -4}) && z == std::vector<double>({1, -2}), "调用者原始种子不得被修改");
  ledger(result, one);
  const auto saved_x = result.x, saved_z = result.z;
  const std::span<const double> aliased_x(result.x), aliased_z(result.z);
  warm::Limits no_step; no_step.max_iterations = 0;
  warm::run(f.view(), no_step, aliased_x, aliased_z, 2, {}, [](Index, const auto&, const auto&) { return false; }, result);
  require(result.x[0] == saved_x[0] / 2 && result.x[1] == saved_x[1] / 2 &&
      result.z[0] == saved_z[0] / 2 && result.z[1] == saved_z[1] / 2,
      "复用输出向量作为下一次种子不得因重置结果使 span 悬空");
  details.push_back("非单位tau种子与非对称一步解析");
}

void zero_and_invalid() {
  const Fixture empty{0, 0, {0}, {}, {}, {}, {}, {}};
  const std::vector<double> nothing;
  warm::Limits limits;
  warm::Result result;
  warm::run(empty.view(), limits, nothing, nothing, 1, {}, [&](Index step, const auto& x, const auto& z) {
    return step == 0 && x.empty() && z.empty();
  }, result);
  require(result.accepted && result.stats.steps_completed == 0, "空系统须由真实种子验收明确接纳");
  const Fixture zero{1, 1, {0, 0}, {}, {}, {1}, {0}, {true}};
  const std::vector<double> x{0}, z{0};
  warm::Limits two; two.max_iterations = 2;
  warm::run(zero.view(), two, x, z, 1, {}, [](Index, const auto&, const auto&) { return false; }, result);
  require(status(result, "iteration_limit") && !result.accepted && std::abs(result.x[0] + 1.8) < 1e-14 && result.z[0] == 0,
          "零矩阵仍须使用合法非零步长，不能伪造最优或不可行证书");
  std::vector<Fixture> bad{
    {-1, 1, {0}, {}, {}, {}, {0}, {true}},
    {1, 1, {}, {}, {}, {0}, {0}, {true}},
    {1, 1, {0, 1}, {1}, {1}, {0}, {0}, {true}},
    {1, 1, {0, 1}, {0}, {std::numeric_limits<double>::infinity()}, {0}, {0}, {true}},
    {1, 1, {0, 0}, {}, {}, {std::numeric_limits<double>::quiet_NaN()}, {0}, {true}},
    {1, 1, {0, 0}, {}, {}, {0}, {0}, {}}
  };
  for (const auto& f : bad) {
    warm::run(f.view(), limits, x, z, 1, {}, [](Index, const auto&, const auto&) { return true; }, result);
    require(status(result, "invalid_input") && !result.accepted && !result.stats.seed_available &&
        result.stats.assessments_started == 0, "坏输入不能调用验收制造接纳");
  }
  for (double tau : {0.0, -1.0, std::numeric_limits<double>::infinity()}) {
    warm::run(zero.view(), limits, x, z, tau, {}, [](Index, const auto&, const auto&) { return true; }, result);
    require(status(result, "invalid_input") && !result.accepted, "非法 tau 不得产生种子");
  }
  const std::vector<double> negative{-1};
  warm::run(zero.view(), limits, x, negative, 1, {}, [](Index, const auto&, const auto&) { return true; }, result);
  require(status(result, "invalid_input") && !result.accepted, "不等式种子乘子须属于非负域");
  details.push_back("零维零矩阵与坏输入拒绝");
}

void numerical_ranges() {
  const Fixture free{1, 0, {0, 0}, {}, {}, {0}, {}, {}};
  warm::Limits limits; limits.max_iterations = 1;
  const std::vector<double> no_z, tiny{std::numeric_limits<double>::denorm_min()};
  warm::Result result;
  warm::run(free.view(), limits, tiny, no_z, 2, {}, [](Index, const auto&, const auto&) { return true; }, result);
  require(status(result, "arithmetic_failure") && !result.accepted && !result.stats.seed_available,
          "非零种子除 tau 下溢不能静默归零再接纳");
  const Fixture overflow{1, 0, {0, 0}, {}, {}, {-std::numeric_limits<double>::max()}, {}, {}};
  const std::vector<double> huge{std::numeric_limits<double>::max()};
  warm::run(overflow.view(), limits, huge, no_z, 1, {}, [](Index, const auto&, const auto&) { return false; }, result);
  require(status(result, "arithmetic_failure") && !result.accepted && result.x == huge && result.stats.steps_completed == 0 &&
      result.stats.steps_started == 1, "试点溢出必须保留已归一化的旧点");
  const Fixture mixed{2, 2, {0, 1, 2}, {0, 1}, {1e150, 1e-150}, {1, -1}, {0, 0}, {true, false}};
  const std::vector<double> zero{0, 0};
  warm::run(mixed.view(), limits, zero, zero, 1, {}, [](Index, const auto&, const auto&) { return false; }, result);
  require(status(result, "iteration_limit") && result.stats.steps_completed == 1 &&
      std::all_of(result.x.begin(), result.x.end(), [](double value) { return std::isfinite(value); }) &&
      std::all_of(result.z.begin(), result.z.end(), [](double value) { return std::isfinite(value); }), "悬殊系数仍须完成有限、非零步长的一步");
  details.push_back("非零下溢试点溢出及悬殊尺度");
}

void iteration_and_work() {
  const Fixture f{1, 1, {0, 1}, {0}, {1}, {-1}, {1}, {true}};
  const std::vector<double> x{0}, z{0};
  for (Index count : {Index{0}, Index{1}, Index{63}, Index{64}, Index{65}, Index{128}}) {
    warm::Limits limits; limits.max_iterations = count;
    warm::Result result;
    std::vector<Index> seen, expected{0};
    for (Index step = 64; step <= count; step += 64) expected.push_back(step);
    if (count % 64 != 0) expected.push_back(count);
    warm::run(f.view(), limits, x, z, 1, {}, [&](Index step, const auto&, const auto&) { seen.push_back(step); return false; }, result);
    require(status(result, "iteration_limit") && !result.accepted && result.stats.steps_completed == count &&
        result.stats.transpose_completed == count && result.stats.multiply_completed == count && seen == expected,
        "固定评估周期与最后未评估点不能遗漏或重复");
    ledger(result, limits);
  }
  warm::Limits full_limits; full_limits.max_iterations = 2;
  warm::Result full, first;
  const warm::Assessment reject = [](Index, const auto&, const auto&) { return false; };
  warm::run(f.view(), full_limits, x, z, 1, {}, reject, full);
  warm::Limits one; one.max_iterations = 1;
  warm::run(f.view(), one, x, z, 1, {}, reject, first);
  for (Index cap : {Index{0}, Index{1}, full.stats.work_units - 1, full.stats.work_units}) {
    warm::Limits limits = full_limits; limits.max_work = cap;
    warm::Result result;
    warm::run(f.view(), limits, x, z, 1, {}, reject, result);
    require(result.stats.work_units <= cap && !result.accepted, "自有工作不得先超额度再拒绝");
    if (cap == full.stats.work_units) require(status(result, "iteration_limit") && result.x == full.x && result.z == full.z,
        "恰好工作额度须可完成相同两步");
    else require(status(result, "work_limit"), "不足工作额度须返回有界停止");
    if (cap == full.stats.work_units - 1) require(result.stats.steps_completed == 1 && result.x == first.x && result.z == first.z &&
        result.stats.last_assessed_step == 1, "提交前工作中断须保留并最终验收前一步");
    ledger(result, limits);
  }
  details.push_back("迭代周期和精确工作额度边界");
}

void callback_transactions() {
  struct BudgetFailure : std::runtime_error { using std::runtime_error::runtime_error; };
  const Fixture f{1, 1, {0, 1}, {0}, {1}, {0}, {1}, {true}};
  const std::vector<double> x{0}, z{0};
  warm::Limits limits; limits.max_iterations = 2;
  warm::Result result;
  bool callback_returned = false, interrupted = false;
  try {
    warm::run(f.view(), limits, x, z, 1, [&] {
      if (callback_returned) throw BudgetFailure("验收后预算结束");
    }, [&](Index, const auto& a, const auto& b) { callback_returned = true; return optimal(f, a, b); }, result);
  } catch (const BudgetFailure& error) { interrupted = std::string_view(error.what()) == "验收后预算结束"; }
  require(interrupted && !result.accepted && status(result, "budget_exception") &&
      result.stats.assessments_completed == 1 && result.stats.last_assessed_step == 0,
      "回调真值之后预算失败不能伪造接纳");
  interrupted = false;
  try { warm::run(f.view(), limits, x, z, 1, {}, [](Index, const auto&, const auto&) -> bool { throw 17; }, result); }
  catch (int value) { interrupted = value == 17; }
  require(interrupted && !result.accepted && status(result, "assessment_exception") &&
      result.stats.assessments_started == 1 && result.stats.assessments_completed == 0, "验收非标准异常须原型透传且不补回调");
  warm::Result full;
  warm::run(f.view(), limits, x, z, 1, {}, [](Index, const auto&, const auto&) { return false; }, full);
  warm::Limits short_work = limits; short_work.max_work = full.stats.work_units - 1;
  warm::run(f.view(), short_work, x, z, 1, {}, [&](Index step, const auto& a, const auto& b) {
    return step > 0 && optimal(f, a, b);
  }, result);
  require(result.accepted && result.stats.steps_completed == 1 && result.stats.steps_started == 2 && optimal(f, result.x, result.z),
      "有界出口只可接纳最后已提交的真实合格点，不提交中断试点");
  details.push_back("验收真值后预算与异常事务");
}

void every_budget_boundary() {
  struct BudgetFailure : std::runtime_error { using std::runtime_error::runtime_error; };
  Fixture f{1, 600, {0, 600}, {}, {}, {-1}, std::vector<double>(600, 1), std::vector<bool>(600, true)};
  for (Index row = 0; row < 600; ++row) { f.rows.push_back(row); f.values.push_back(1); }
  const std::vector<double> x{-2}, z(600, 0);
  warm::Limits limits; limits.max_iterations = 3; limits.check_interval = 2;
  const warm::Assessment reject = [](Index, const auto&, const auto&) { return false; };
  std::vector<warm::Result> reference;
  for (Index count = 0; count <= 3; ++count) {
    warm::Limits prefix = limits; prefix.max_iterations = count;
    warm::Result result;
    warm::run(f.view(), prefix, x, z, 1, {}, reject, result);
    reference.push_back(std::move(result));
  }
  Index checks = 0, first_transpose_checks = 0;
  warm::Result full;
  warm::run(f.view(), limits, x, z, 1, [&] {
    ++checks;
    if (full.stats.transpose_started == 1 && full.stats.transpose_completed == 0) ++first_transpose_checks;
  }, reject, full);
  require(checks == full.stats.budget_checks && first_transpose_checks >= 3,
          "长列转置乘积除前后边界外必须实际触发元素工作预算检查");
  for (Index stop = 1; stop <= checks; ++stop) {
    Index calls = 0;
    bool interrupted = false;
    warm::Result result;
    try {
      warm::run(f.view(), limits, x, z, 1, [&] { if (++calls == stop) throw BudgetFailure("长列独立预算结束"); }, reject, result);
    } catch (const BudgetFailure& error) { interrupted = std::string_view(error.what()) == "长列独立预算结束"; }
    require(interrupted && !result.accepted && status(result, "budget_exception"), "每个真实预算边界须原型透传");
    if (result.stats.seed_available) {
      const auto& saved = reference[static_cast<std::size_t>(result.stats.steps_completed)];
      require(result.x == saved.x && result.z == saved.z, "中途异常不得污染上一次完整提交的双向量");
    } else require(result.x.empty() && result.z.empty(), "不完整归一化种子不得对外提交");
    ledger(result, limits);
  }
  details.push_back("长列每真实预算边界原异常及双提交");
}

}  // 匿名命名空间

int main() {
  try {
    convergence(); seed_and_step(); zero_and_invalid(); numerical_ranges();
    iteration_and_work(); callback_transactions(); every_budget_boundary();
    const warm::Limits defaults;
    std::printf("{\"passed\":true,\"public_lp_runs\":0,\"cases\":%zu,\"default_limits\":{"
        "\"max_iterations\":%lld,\"max_work_units\":%lld,\"check_interval\":%lld,"
        "\"budget_check_work_interval\":%lld,\"step_safety\":%.17g},\"details\":[", details.size(),
        static_cast<long long>(defaults.max_iterations), static_cast<long long>(defaults.max_work),
        static_cast<long long>(defaults.check_interval), static_cast<long long>(warm::budget_check_work_interval),
        static_cast<double>(warm::step_safety));
    for (std::size_t i = 0; i < details.size(); ++i) std::printf("%s\"%s\"", i ? "," : "", details[i]);
    std::puts("]}");
    return 0;
  } catch (const std::exception& error) {
    std::fprintf(stderr, "warm PDHG隔离检查失败：%s\n", error.what());
    return 1;
  }
}

v84-ipm-self-test.cpp.source:
#include "ipm-warm.cpp"

#include <cstdio>
#include <iostream>
#include <string>

namespace {
int cases = 0, mapping_cases = 0, isolation_cases = 0;
int verification_accounting_cases = 0, budget_cases = 0, exception_cases = 0;
const double infinity = std::numeric_limits<double>::infinity();

void require(bool condition, const char* message) {
  if (!condition) throw std::runtime_error(message);
}

solver::SolveOptions policy() {
  solver::SolveOptions options;
  options.time_limit = 60;
  options.ipm.objective_scaling = false;
  options.ipm.eliminate_fixed_variables = true;
  return options;
}

solver::Model mapped_model(bool maximum = false) {
  solver::Model model;
  model.sense = maximum ? solver::ObjectiveSense::maximize : solver::ObjectiveSense::minimize;
  model.objective_offset = 11;
  model.costs = {7, maximum ? -2.0 : 2.0, 0};
  model.column_lower = {3, 0, -infinity}; model.column_upper = {3, 10, infinity};
  model.row_lower = {16, -infinity, -25}; model.row_upper = {16, 40, infinity};
  model.kinds.assign(3, solver::VariableKind::continuous);
  model.column_start = {0, 0, 1, 3}; model.row_index = {0, 1, 2}; model.values = {8, 10, 5};
  return model;
}

solver::Model merged_model(bool upper, bool fixed = false, bool maximum = false) {
  solver::Model model;
  model.sense = maximum ? solver::ObjectiveSense::maximize : solver::ObjectiveSense::minimize;
  model.costs = {upper ? -3.0 : 3.0};
  model.column_lower = {-infinity}; model.column_upper = {infinity};
  model.row_lower = {8, -infinity}; model.row_upper = {infinity, fixed ? 4.0 : 10.0};
  model.kinds.assign(1, solver::VariableKind::continuous);
  model.column_start = {0, 2}; model.row_index = {0, 1}; model.values = {4, 2};
  return model;
}

solver::SolveResult original(const solver::Model& model) {
  solver::SolveResult result;
  result.model = model;
  result.backend = "ipm"; result.backend_version = "v66-unchanged";
  result.status = "numerical_error"; result.backend_status = "original_status";
  result.message = "原错误不能被恢复失败替换"; result.verification_level = "original_level";
  result.has_solution = true; result.solution = {101}; result.row_dual = {202};
  result.objective = 303; result.best_bound = 304; result.absolute_gap = 305; result.relative_gap = 306;
  result.verification.objective = 307; result.verification.errors = {"原诊断"};
  result.lp_optimality.emplace(); result.lp_optimality->objective_gap = 308;
  result.verification_seconds = 7;
  result.ipm_iterations = 137; result.ipm_factorizations = 11; result.ipm_refinement_steps = 19;
  result.ipm_homogeneous_constant_solves = 139; result.ipm_homogeneous_direction_solves = 275;
  return result;
}

void same_payload(const solver::SolveResult& value, const solver::SolveResult& before) {
  require(value.backend == before.backend && value.backend_version == before.backend_version &&
      value.backend_status == before.backend_status && value.status == before.status && value.message == before.message &&
      value.verification_level == before.verification_level && value.has_solution == before.has_solution &&
      value.solution == before.solution && value.row_dual == before.row_dual && value.objective == before.objective &&
      value.best_bound == before.best_bound && value.absolute_gap == before.absolute_gap && value.relative_gap == before.relative_gap &&
      value.verification.objective == before.verification.objective && value.verification.errors == before.verification.errors &&
      value.verification.valid_input == before.verification.valid_input && value.verification.feasible == before.verification.feasible &&
      value.lp_optimality.has_value() == before.lp_optimality.has_value() &&
      (!value.lp_optimality || value.lp_optimality->objective_gap == before.lp_optimality->objective_gap) &&
      value.model.values == before.model.values && value.model.costs == before.model.costs &&
      value.model.column_lower == before.model.column_lower && value.model.row_lower == before.model.row_lower &&
      value.ipm_iterations == before.ipm_iterations && value.ipm_factorizations == before.ipm_factorizations &&
      value.ipm_refinement_steps == before.ipm_refinement_steps &&
      value.ipm_homogeneous_constant_solves == before.ipm_homogeneous_constant_solves &&
      value.ipm_homogeneous_direction_solves == before.ipm_homogeneous_direction_solves,
      "未提交恢复不得污染原解、质量、状态、模型、后端或legacy计数");
}

solver::Point seed(const solver::ConeModel& cone, const std::vector<double>& x, const std::vector<double>& y,
    double tau = 1) {
  solver::Point point;
  point.x.resize(cone.costs.size()); point.z.assign(cone.rhs.size(), 0);
  for (std::size_t col = 0; col < point.x.size(); ++col) {
    const auto original_col = cone.original_columns.empty() ? col : cone.original_columns[col];
    point.x[col] = (x[original_col] / cone.column_scale[col]) * tau;
  }
  for (std::size_t row = 0; row < point.z.size(); ++row) {
    if (cone.original_row[row] < 0) continue;
    const auto original_row = static_cast<std::size_t>(cone.original_row[row]);
    const double z = y[original_row] / (cone.dual_sign[row] * cone.row_scale[row] * cone.objective_scale);
    if (!cone.inequality[row] || z >= 0) point.z[row] = z * tau;
  }
  for (const auto& recovery : cone.presolved_bounds) {
    double multiplier = 0;
    if (recovery.lower.row >= 0) multiplier = y[static_cast<std::size_t>(recovery.lower.row)] * recovery.lower.coefficient;
    if (multiplier == 0 && recovery.upper.row >= 0)
      multiplier = y[static_cast<std::size_t>(recovery.upper.row)] * recovery.upper.coefficient;
    const auto row = static_cast<std::size_t>(recovery.cone_row);
    const double z = multiplier / (recovery.sign * cone.row_scale[row] * cone.objective_scale);
    if (!cone.inequality[row] || z >= 0) point.z[row] = z * tau;
  }
  return point;
}

void mapping(const solver::Model& model, const std::vector<double>& known_x, const std::vector<double>& known_y,
    solver::SolveOptions options, bool use_kernel = true) {
  const auto start = solver::Clock::now();
  const auto cone = solver::canonicalize(model, options, start);
  auto result = original(model);
  const auto before = result;
  const auto model_storage = result.model.values.data();
  solver_v84_warm_state::Log log;
  log.enabled = true;
  bool accepted;
  if (use_kernel) {
    const double tau = std::ldexp(1.0, -40);
    const auto point = seed(cone, known_x, known_y, tau);
    accepted = solver::v84_try_warm(cone, point, tau, 0.125, options, start, result, log);
    require(log.attempted && log.accepted && log.kernel.accepted && log.kernel.stats.steps_started == 0,
        "原模型已验收种子应直接通过，不伪造PDHG迭代");
  } else {
    // 输入归并后全固定的模型会在原HSD主循环前早退；这里只测试同一实际assess适配器的映射。
    const auto point = seed(cone, known_x, known_y);
    solver::V84WarmAssessment assessment(cone, options, start, result, log);
    accepted = assessment(0, point.x, point.z);
    require(accepted && assessment.pending, "全固定映射必须经原assess通过");
    solver::check_budget(options, start);
    assessment.commit();
  }
  require(accepted && result.status == "optimal" && result.has_solution && result.verification.feasible &&
      result.lp_optimality && result.lp_optimality->numerically_optimal && log.seed_quality && log.last_quality &&
      log.seed_quality->completed_steps == 0 && log.last_quality->numerically_optimal == std::optional<bool>(true),
      "原坐标映射和原完整终验必须决定接纳");
  require(result.solution.size() == known_x.size() && result.row_dual.size() == known_y.size(), "恢复必须保留原维数");
  for (std::size_t col = 0; col < known_x.size(); ++col)
    require(std::abs(result.solution[col] - known_x[col]) <= 1e-11 * std::max(1.0, std::abs(known_x[col])),
        "固定列和列scale必须恢复原primal");
  for (std::size_t row = 0; row < known_y.size(); ++row)
    require(std::abs(result.row_dual[row] - known_y[row]) <= 1e-9 * std::max(1.0, std::abs(known_y[row])),
        "行scale、上下界来源和目标方向必须恢复原dual");
  require(result.backend == before.backend && result.backend_version == before.backend_version &&
      result.backend_status == before.backend_status && result.model.values.data() == model_storage &&
      result.ipm_iterations == before.ipm_iterations && result.ipm_factorizations == before.ipm_factorizations &&
      result.ipm_refinement_steps == before.ipm_refinement_steps &&
      result.ipm_homogeneous_constant_solves == before.ipm_homogeneous_constant_solves &&
      result.ipm_homogeneous_direction_solves == before.ipm_homogeneous_direction_solves &&
      result.verification_seconds >= before.verification_seconds, "接纳只搬质量，不覆盖原计数或模型");
  ++mapping_cases; ++cases;
}

void check_current_quality() {
  auto options = policy(); const auto model = mapped_model(); const auto start = solver::Clock::now();
  const auto cone = solver::canonicalize(model, options, start);
  const auto good = seed(cone, {3, 2, 0}, {0.25, 0, 0});
  auto bad = good; bad.x[0] += 1;
  auto result = original(model); const auto before = result;
  solver_v84_warm_state::Log log;
  solver::V84WarmAssessment assessment(cone, options, start, result, log);
  require(assessment(0, good.x, good.z), "第一次原验收应通过");
  require(!assessment(64, bad.x, bad.z) && !assessment.pending && log.seed_quality->primal_feasible &&
      !log.last_quality->primal_feasible && log.last_quality->completed_steps == 64,
      "每次force当前点质量，不能把前一个可行点误记到last_quality");
  same_payload(result, before);
  ++isolation_cases; ++cases;
}

void check_off() {
  auto options = policy(); options.time_limit = 0;
  auto result = original(mapped_model()); const auto before = result;
  solver::ConeModel cone; solver::Point point; solver_v84_warm_state::Log log;
  require(!solver::v84_try_warm(cone, point, 0, 0, options, solver::Clock::now(), result, log) &&
      !log.attempted && !log.accepted && !log.seed_quality && !log.last_quality, "关闭不能启动恢复或改变原失败");
  same_payload(result, before);
  require(result.verification_seconds == before.verification_seconds, "关闭不得伪造验收成本");
  ++isolation_cases; ++cases;
}

void check_entry_budget() {
  auto options = policy(); options.time_limit = 0;
  auto result = original(mapped_model()); const auto before = result;
  solver::ConeModel cone; solver::Point point; solver_v84_warm_state::Log log; log.enabled = true;
  bool interrupted = false;
  try { solver::v84_try_warm(cone, point, 1, 1, options, solver::Clock::now(), result, log); }
  catch (const solver::BudgetExpired&) { interrupted = true; }
  require(interrupted && !log.attempted && !log.accepted && !log.seed_quality, "原截止时间已到时不得抢先记作启动恢复");
  same_payload(result, before);
  require(result.verification_seconds == before.verification_seconds, "未启动assessment不能伪造计时");
  ++budget_cases; ++cases;
}

void check_pending_budget() {
  auto options = policy(); const auto model = mapped_model(); const auto start = solver::Clock::now();
  const auto cone = solver::canonicalize(model, options, start);
  const auto good = seed(cone, {3, 2, 0}, {0.25, 0, 0});
  auto result = original(model); const auto before = result;
  solver_v84_warm_state::Log log;
  solver::V84WarmAssessment assessment(cone, options, start, result, log);
  require(assessment(0, good.x, good.z) && assessment.pending, "先取得真实已核pending候选");
  options.time_limit = 0;
  bool interrupted = false;
  try { solver::check_budget(options, start); assessment.commit(); }
  catch (const solver::BudgetExpired&) { interrupted = true; }
  require(interrupted && !log.accepted && log.last_quality->numerically_optimal == std::optional<bool>(true),
      "已核质量不等于提交，原预算仍可拒绝pending候选");
  same_payload(result, before);
  ++budget_cases; ++cases;
}

void check_assessment_budget() {
  auto options = policy(); options.ipm.presolve_singleton_rows = true;
  const auto model = merged_model(false); const auto start = solver::Clock::now();
  const auto cone = solver::canonicalize(model, options, start);
  require(!cone.presolved_bounds.empty(), "预算fixture必须实际进入原界乘子恢复");
  const auto good = seed(cone, {2}, {0.75, 0});
  auto result = original(model); const auto before = result;
  solver_v84_warm_state::Log log;
  solver::V84WarmAssessment assessment(cone, options, start, result, log);
  options.time_limit = 0;
  bool interrupted = false;
  try { assessment(0, good.x, good.z); }
  catch (const solver::BudgetExpired&) { interrupted = true; }
  require(interrupted && !log.seed_quality && !log.last_quality && !assessment.pending,
      "原assess中途预算须保原类型且不得伪造完整质量");
  same_payload(result, before);
  require(result.verification_seconds >= before.verification_seconds, "抛异常的assessment实际时间也须累计");
  ++budget_cases; ++cases;
}

void check_accounting(bool failure) {
  auto options = policy(); const auto model = mapped_model(); const auto start = solver::Clock::now();
  auto cone = solver::canonicalize(model, options, start);
  const auto good = seed(cone, {3, 2, 0}, {0.25, 0, 0});
  auto result = original(model); const auto before = result;
  if (failure) cone.column_scale[0] = infinity;
  solver_v84_warm_state::Log log;
  solver::V84WarmAssessment assessment(cone, options, start, result, log);
  const auto model_storage = assessment.trial.model.values.data();
  assessment.trial.verification_seconds = 1000;
  const auto timing_begin = solver::Clock::now();
  bool threw = false;
  try { assessment(0, good.x, good.z); }
  catch (const solver::NumericalFailure&) { threw = true; }
  const double total = solver::elapsed(timing_begin);
  require(threw == failure && result.verification_seconds >= before.verification_seconds &&
      result.verification_seconds - before.verification_seconds <= total + 1e-9 &&
      assessment.trial.verification_seconds < 1000 && assessment.trial.model.values.data() == model_storage,
      "assessment只记本次真实调用成本，不累计旧trial计时或重复复制model");
  if (failure) require(!log.seed_quality && !log.last_quality, "未完成原assess时质量必须为null");
  else require(result.verification_seconds - before.verification_seconds + 1e-9 >= assessment.trial.verification_seconds,
      "完整原assess内层验收成本不能漏计");
  same_payload(result, before);
  ++verification_accounting_cases; ++cases;
}

void check_original_exception() {
  auto options = policy(); const auto model = mapped_model(); const auto start = solver::Clock::now();
  auto cone = solver::canonicalize(model, options, start);
  const auto good = seed(cone, {3, 2, 0}, {0.25, 0, 0});
  cone.column_scale[0] = infinity;
  auto result = original(model); const auto before = result;
  solver_v84_warm_state::Log log; log.enabled = true;
  bool original_preserved = false;
  try {
    try { throw solver::NumericalFailure("原主循环数值失败"); }
    catch (const solver::NumericalFailure&) {
      if (solver::v84_try_warm(cone, good, 1, 1, options, start, result, log))
        throw std::runtime_error("异常fixture不得接纳");
      throw;
    }
  } catch (const solver::NumericalFailure& error) {
    original_preserved = std::string(error.what()) == "原主循环数值失败";
  }
  require(original_preserved && log.attempted && !log.accepted && std::string(log.status) == "exception" &&
      !log.seed_quality && !log.last_quality, "warm自己的验收异常不能吞掉或替换原异常");
  same_payload(result, before);
  ++exception_cases; ++cases;
}
}  // 匿名命名空间

int main() {
  try {
    for (const bool maximum : {false, true}) for (const bool scale_objective : {false, true}) {
      auto options = policy(); options.ipm.objective_scaling = scale_objective;
      mapping(mapped_model(maximum), {3, 2, 0}, {0.25, 0, 0}, options);
    }
    for (const bool upper : {false, true}) {
      auto options = policy(); options.ipm.presolve_singleton_rows = true;
      mapping(merged_model(upper), {upper ? 5.0 : 2.0}, upper ? std::vector<double>{0, -1.5} : std::vector<double>{0.75, 0}, options);
    }
    for (const bool maximum : {false, true}) {
      auto options = policy(); options.ipm.presolve_singleton_rows = true; options.ipm.eliminate_presolved_fixed_variables = true;
      mapping(merged_model(false, true, maximum), {2}, maximum ? std::vector<double>{0, -1.5} : std::vector<double>{0.75, 0}, options, false);
    }
    check_current_quality(); check_off(); check_entry_budget(); check_pending_budget(); check_assessment_budget();
    check_accounting(false); check_accounting(true); check_original_exception();
    std::printf("{\"passed\":true,\"solver_runs\":0,\"cases\":%d,\"mapping_cases\":%d,\"isolation_cases\":%d,"
        "\"verification_accounting_cases\":%d,\"budget_cases\":%d,\"exception_cases\":%d}\n",
        cases, mapping_cases, isolation_cases, verification_accounting_cases, budget_cases, exception_cases);
    return 0;
  } catch (const std::exception& error) {
    std::cerr << error.what() << '\n';
    return 1;
  }
}

